      expect(
        await service.readSub(f.id, 'items', f.ids[0], {
          populate: [{ path: 'ref', authorization: { outputFields: { mode: 'unrestricted' } } }],
        }),
      ).toMatchObject({ success: false, code: 'bad_request' });
      const nested = await publicService._read(f.id, {
        include: {
          model: f.targetName,
          op: 'read',
