it('undefined omits; throw omits with structural log only', async () => {
    const warnSpy = vi.spyOn(loggerHelpers, 'warn').mockImplementation(() => {});
    const undefGet = vi.fn(async () => undefined);
    const throwGet = vi.fn(async () => {
