      } as never,
    });
    const plan = planVirtualProjection({
      receivingModelName: 'U',
      snapshot,
      virtualAccess: READ,
      outputAccess: READ,
      docPermissionsAccess: READ,
      requestedSelect: ['name', 'vUndef', 'vThrow'],
      globalPermissions: nonePerms,
    });
