      snapshot,
      request: mockRequest(),
      context: baseContext(),
      docPermissions: {},
      globalPermissions: nonePerms,
    });
    expect(out).not.toHaveProperty('vUndef');
    expect(out).not.toHaveProperty('vThrow');
