    const serialized = JSON.stringify([msg, meta]);
    expect(serialized).not.toContain('boom');
    expect(Object.keys(meta).sort()).toEqual(
      ['category', 'field', 'modelName', 'operation', 'outputAccess', 'scope', 'virtualAccess'].sort(),
    );
  })

