                              localField: 'key',
                              foreignField: 'key',
                              args: { select: ['account', 'total'] },
                            },
                          ],
                        },
                  quiet,
                );
          const pending = read();
          await ready;
          f.api.setDefaultModelOption('requireOperationAccessForPopulateDependencies', !strict);
          release();
          return [await pending, await read()];
        });
        for (const [index, result] of results.entries()) {
          expect(result).toMatchObject({ success: true });
          if (!result.success) throw new Error(result.code);
          const data = result.data as Row;
          const row =
            stage === 'embedded'
              ? data.children[0]
              : stage === 'populated'
                ? data.members[0]
                : stage === 'include'
                  ? data.joined
                  : data;
          expect(row.account).toEqual(f.a._id);
          if (index === 0 ? strict : !strict) expect(row).not.toHaveProperty('total');
          else expect(row).toHaveProperty('total', 'read:10');
        }
      },
    )

