    expect(f.total.mock.calls[0][2]).toMatchObject({ operation: 'subList', docPermissionsAccess: 'read' });
    expect(
      f.total.mock.calls.find(([, , context]) => context.scopePath.join('.') === 'children.sub.notes.sub')![0],
    ).not.toHaveProperty('account');
  })

